using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 2), ("Gadget", 25.50m, 1));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(45.50m, order.Total);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
    {
        var items = CreateItems(("Widget", 15.00m, 3));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.AreEqual(45.00m, order.Total);
        Assert.ContainsSingle(order.Items);
    }

    [TestMethod]
    public void CreateOrder_AssignsUniqueId()
    {
        var items = CreateItems(("Widget", 5.00m, 1));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.IsNotNull(order.Id);
        Assert.IsNotEmpty(order.Id);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.UtcNow;
        var items = CreateItems(("Widget", 5.00m, 1));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.IsInRange(order.CreatedAt, before, DateTime.UtcNow);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems(("Widget", 5.00m, 1));

        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _sut.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _sut.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _sut.CreateOrder("cust-1", []));
    }

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsOrder()
    {
        var items = CreateItems(("Widget", 5.00m, 1));
        var created = _sut.CreateOrder("cust-1", items);

        var retrieved = _sut.GetOrder(created.Id);

        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _sut.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        _sut.CreateOrder("cust-1", CreateItems(("A", 1m, 1)));
        _sut.CreateOrder("cust-1", CreateItems(("B", 2m, 1)));
        _sut.CreateOrder("cust-2", CreateItems(("C", 3m, 1)));

        var orders = _sut.GetOrdersByCustomer("cust-1");

        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var orders = _sut.GetOrdersByCustomer("no-orders");

        Assert.IsEmpty(orders);
    }

    [TestMethod]
    [DataRow(10.00, 3, 30.00, DisplayName = "Multiple quantity")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 1, 99.99, DisplayName = "Single quantity")]
    public void CreateOrder_CalculatesTotal_FromPriceTimesQuantity(
        double price, int qty, double expectedTotal)
    {
        var items = CreateItems(("Item", (decimal)price, qty));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.AreEqual((decimal)expectedTotal, order.Total);
    }
}

